package com.triathlon.prep.core;
import java.io.*;import java.util.*;import java.util.zip.CRC32;
/** One app-private versioned/checksummed atomic template. No defaults are written on load. */
public final class FileReceiptTemplateStore {
 private static final int MAGIC=0x52545031;private final File file,pending,backup;
 public FileReceiptTemplateStore(File directory)throws IOException{if(directory==null||(!directory.exists()&&!directory.mkdirs())||!directory.isDirectory())throw new IOException("Private template storage unavailable");file=new File(directory,"template.bin");pending=new File(directory,"template.bin.new");backup=new File(directory,"template.bin.bak");}
 public synchronized ReceiptTemplate load()throws IOException{recover();if(!file.exists())return null;if(!file.isFile()||file.length()<16||file.length()>65536)throw new IOException("Invalid template snapshot");byte[] bytes=new byte[(int)file.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(file))){in.readFully(bytes);if(in.read()!=-1)throw new IOException("Template changed during read");}return decode(bytes);}
 public synchronized void replace(ReceiptTemplate template)throws IOException{if(template==null)throw new IOException("Validated template required");byte[] bytes=encode(template);recover();try(FileOutputStream out=new FileOutputStream(pending)){out.write(bytes);out.flush();out.getFD().sync();}if(file.exists()&&!file.renameTo(backup))throw new IOException("Cannot preserve previous template");if(!pending.renameTo(file)){if(backup.exists()&&!backup.renameTo(file))throw new IOException("Template restore failed");throw new IOException("Template replace failed");}if(backup.exists()&&!backup.delete())throw new IOException("Template commit cleanup failed");}
 private void recover()throws IOException{if(backup.exists()){if(file.exists()&&!file.delete())throw new IOException("Cannot recover template");if(!backup.renameTo(file))throw new IOException("Cannot restore template");}if(pending.exists()&&!pending.delete())throw new IOException("Cannot discard interrupted template write");}
 public static byte[] encode(ReceiptTemplate template)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeInt(1);for(ReceiptTemplate.TextKey key:ReceiptTemplate.TextKey.values())out.writeUTF(template.text(key));for(ReceiptTemplate.ItemSpec item:template.items){out.writeUTF(item.id.name());out.writeUTF(item.label);out.writeBoolean(item.visible);}for(ReceiptTemplate.Section section:ReceiptTemplate.Section.values()){ReceiptTemplate.Style style=template.style(section);out.writeUTF(style.size.name());out.writeBoolean(style.bold);out.writeUTF(style.align.name());out.writeUTF(style.spacing.name());}out.flush();CRC32 crc=new CRC32();byte[] body=bytes.toByteArray();crc.update(body);out.writeLong(crc.getValue());}return bytes.toByteArray();}
 public static ReceiptTemplate decode(byte[] bytes)throws IOException{if(bytes==null||bytes.length<16||bytes.length>65536)throw new IOException("Invalid template bytes");CRC32 crc=new CRC32();crc.update(bytes,0,bytes.length-8);try(DataInputStream tail=new DataInputStream(new ByteArrayInputStream(bytes,bytes.length-8,8))){if(tail.readLong()!=crc.getValue())throw new IOException("Template checksum failed");}try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes,0,bytes.length-8))){if(in.readInt()!=MAGIC||in.readInt()!=1)throw new IOException("Unknown template format");EnumMap<ReceiptTemplate.TextKey,String> text=new EnumMap<>(ReceiptTemplate.TextKey.class);for(ReceiptTemplate.TextKey key:ReceiptTemplate.TextKey.values())text.put(key,in.readUTF());List<ReceiptTemplate.ItemSpec> items=new ArrayList<>();for(int i=0;i<CheckInReceipt.Item.values().length;i++)items.add(new ReceiptTemplate.ItemSpec(CheckInReceipt.Item.valueOf(in.readUTF()),in.readUTF(),in.readBoolean()));EnumMap<ReceiptTemplate.Section,ReceiptTemplate.Style> styles=new EnumMap<>(ReceiptTemplate.Section.class);for(ReceiptTemplate.Section section:ReceiptTemplate.Section.values())styles.put(section,new ReceiptTemplate.Style(ReceiptTemplate.FontSize.valueOf(in.readUTF()),in.readBoolean(),ReceiptTemplate.Align.valueOf(in.readUTF()),ReceiptTemplate.Spacing.valueOf(in.readUTF())));if(in.read()!=-1)throw new IOException("Trailing template data");return new ReceiptTemplate(text,items,styles);}catch(IllegalArgumentException ex){throw new IOException("Invalid template configuration",ex);}}
}
